<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ValueObject\ConsentPurposeTenantVO;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;

trait ConsentPurposeTenantAttributeHolder
{
    protected ConsentPurposeTenantVO|TenantRef|null $tenant = null;
    protected bool $tenantAssigned = false;

    public function getTenantOrCurrent(ConsentPurposeTenantVO $tenant): ConsentPurposeTenantVO
    {
        if ($this->tenantAssigned) {
            \assert(null !== $this->tenant);
            return ConsentPurposeTenantVO::from($this->tenant);
        } else {
            return $tenant;
        }
    }
    public function tenantTryBuildInitial(ConstraintFailList $error): ?ConsentPurposeTenantVO
    {
        return  ConsentPurposeTenantVO::tryFrom($this->tenantAssigned ? $this->tenant : null, $error);
    }
    public function tenant(ConsentPurposeTenantVO|TenantRef $tenant): static
    {
        $this->tenant = $tenant;
        $this->tenantAssigned = true;
        return $this;
    }
    public function getTenant(): ?TenantRef
    {
        return $this->tenant instanceof ConsentPurposeTenantVO ? $this->tenant->value() : $this->tenant;
    }
    public function isTenantAssigned(): bool
    {
        return $this->tenantAssigned;
    }
    public function writeTenantTo(mixed $att): void
    {
        if ($this->tenantAssigned) {
            \assert(null !== $this->tenant);
            $att->tenant($this->tenant);
        }
    }
    public function readTenantFrom(mixed $att): void
    {
        if ($att->isTenantAssigned()) {
            $tenant = $att->getTenant();
            \assert(null !== $tenant);
            $this->tenant($tenant);
        }
    }
    public function unsetTenant(): static
    {
        $this->tenantAssigned = false;
        return $this;
    }
    protected function withDefaultTenant(): void
    {
    }
    protected function withAssertedTenantRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->tenantAssigned = $this->tenantAssigned) {
            $value->tenant = ConsentPurposeTenantVO::tryFrom($this->tenant, $errorsList);
        }
    }
}
